package com.villaserena.api.piso;
import java.util.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import com.villaserena.api.auth.UsuarioActual;
import com.villaserena.api.comun.ApiException;
import com.villaserena.api.reservas.IdempotenciaReservas;
import tools.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
/** Edición de catálogos existentes sin recrearlos ni recalcular reservas ya guardadas. */
@RestController @RequestMapping("/api/v1/admin/catalogos") @PreAuthorize("hasRole('ADMIN')")
public class AdministracionCatalogos {
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final IdempotenciaReservas solicitudes;private final PasswordEncoder encoder;
 public AdministracionCatalogos(JdbcTemplate jdbc,ObjectMapper mapper,IdempotenciaReservas solicitudes,PasswordEncoder encoder){this.jdbc=jdbc;this.mapper=mapper;this.solicitudes=solicitudes;this.encoder=encoder;}
 public record Guardar(@NotNull UUID clave,Long id,@Min(0) long version,@NotNull Map<String,Object> datos){}
 private ApiException invalid(String s){return ApiException.datosInvalidos(s,List.of());}
 private String tabla(String r){return switch(r){case "tipos"->"room_types";case "habitaciones"->"rooms";case "personal"->"employees";case "temporadas"->"seasons";default->throw ApiException.noEncontrado();};}
 private List<Map<String,Object>> registros(String recurso){return switch(recurso){case "tipos"->jdbc.queryForList("SELECT id,name AS \"nombre\",description AS \"descripcion\",capacity AS \"capacidad\",base_price AS \"precioBase\",weekend_adjustment_pct AS \"ajusteFinSemanaPct\",status AS \"estado\",version  FROM room_types ORDER BY id");case "habitaciones"->jdbc.queryForList("SELECT id,number AS \"numero\",floor AS \"piso\",room_type_id AS \"tipoHabitacionId\",occupancy AS \"ocupacion\",condition AS \"condicion\",status AS \"estado\",version  FROM rooms ORDER BY floor,number");case "personal"->jdbc.queryForList("SELECT id,full_name AS nombre,email AS \"correo\",phone AS \"telefono\",role AS \"rol\",area,status AS \"estado\",profile AS \"perfil\",version  FROM employees ORDER BY id");case "temporadas"->jdbc.queryForList("SELECT t.id,t.name AS \"nombre\",t.start_date AS desde,t.end_date AS hasta,t.adjustment_pct AS \"ajustePct\",t.applies_to_all AS \"aplicaATodos\",t.active AS \"activa\",t.version,coalesce((SELECT jsonb_agg(tt.room_type_id) FROM season_room_types tt WHERE tt.season_id=t.id),'[]'::jsonb) AS tipos  FROM seasons t ORDER BY t.start_date,t.id");default->throw ApiException.noEncontrado();};}
 @GetMapping("/{recurso}") public List<Map<String,Object>> lista(@PathVariable String recurso){var rows=registros(recurso);for(var row:rows){for(String k:List.of("perfil","tipos")){var v=row.get(k);if(v!=null)row.put(k,k.equals("perfil")?mapper.readValue(v.toString(),Map.class):mapper.readValue(v.toString(),List.class));}for(String k:List.of("desde","hasta")){var v=row.get(k);if(v!=null)row.put(k,v.toString());}}return rows;}
 @PostMapping("/{recurso}") public Map<?,?> guardar(@PathVariable String recurso,@Valid @RequestBody Guardar p){tabla(recurso);if(mapper.writeValueAsString(p.datos()).length()>32000)throw invalid("Datos demasiado largos.");return solicitudes.ejecutar("admin:"+UsuarioActual.id()+":"+recurso,p.clave().toString(),p,Map.class,()->cambiar(recurso,p));}
 private String texto(Map<String,Object>d,String k,int max){if(!(d.get(k) instanceof String s)||s.isBlank()||s.length()>max)throw invalid("Revisa "+k+".");return s.trim();}
 private BigDecimal num(Map<String,Object>d,String k,BigDecimal min){try{BigDecimal n=new BigDecimal(String.valueOf(d.get(k)));if(n.compareTo(min)<0||n.compareTo(new BigDecimal("9999999"))>0||n.scale()>2)throw invalid("Revisa "+k+".");return n;}catch(NumberFormatException e){throw invalid("Revisa "+k+".");}}
 private long entero(Map<String,Object>d,String k,long min){try{return num(d,k,BigDecimal.valueOf(min)).longValueExact();}catch(ArithmeticException e){throw invalid("Revisa "+k+".");}}
 private String estado(Map<String,Object>d){String s=String.valueOf(d.get("estado"));if(!Set.of("ACTIVO","INACTIVO").contains(s))throw invalid("Estado inválido.");return s;}
 private Map<String,Object> cambiar(String recurso,Guardar p){String t=tabla(recurso);Map<String,Object> old=null;if(p.id()!=null){var rows=jdbc.queryForList("SELECT to_jsonb(x)::text AS datos,version  FROM "+t+" x WHERE id=? FOR UPDATE",p.id());if(rows.isEmpty())throw ApiException.noEncontrado();if(((Number)rows.getFirst().get("version")).longValue()!=p.version())throw ApiException.conflicto("VERSION_CAMBIADA","El registro cambió. Actualiza antes de guardar.");old=mapper.readValue((String)rows.getFirst().get("datos"),Map.class);if(recurso.equals("personal"))old.remove("password_hash");}var d=p.datos();Long id=p.id();String temporal=null;
  switch(recurso){
   case "tipos"->{String nombre=texto(d,"nombre",100),descripcion=texto(d,"descripcion",4000),state=estado(d);long cap=entero(d,"capacidad",1);if(cap>30)throw invalid("La capacidad máxima es 30.");BigDecimal precio=num(d,"precioBase",new BigDecimal("0.01")),ajuste=num(d,"ajusteFinSemanaPct",new BigDecimal("-99.99"));if(id!=null&&jdbc.queryForObject("SELECT count(*)  FROM reservations WHERE room_type_id=? AND status IN ('CONFIRMADA','EN_ESTADIA','PENDIENTE_PAGO') AND (guest_count>? OR ?='INACTIVO')",Integer.class,id,cap,state)>0)throw ApiException.conflicto("RESERVAS_ACTIVAS","El cambio afecta reservas activas.");if(id==null)id=jdbc.queryForObject("INSERT INTO room_types(name,description,capacity,base_price,weekend_adjustment_pct,status) VALUES(?,?,?,?,?,?) RETURNING id",Long.class,nombre,descripcion,cap,precio,ajuste,state);else jdbc.update("UPDATE room_types SET name=?,description=?,capacity=?,base_price=?,weekend_adjustment_pct=?,status=?,version=version+1 WHERE id=?",nombre,descripcion,cap,precio,ajuste,state,id);}
   case "habitaciones"->{String numero=texto(d,"numero",10),state=estado(d);long piso=entero(d,"piso",1),tipo=entero(d,"tipoHabitacionId",1);if(piso>100)throw invalid("Piso inválido.");if(jdbc.queryForObject("SELECT count(*)  FROM rooms WHERE number=? AND id<>?",Integer.class,numero,id==null?-1:id)>0)throw ApiException.conflicto("HABITACION_EXISTENTE","Ese número de habitación ya existe.");if(jdbc.queryForObject("SELECT count(*)  FROM room_types WHERE id=? AND status='ACTIVO'",Integer.class,tipo)!=1)throw invalid("Selecciona un tipo activo.");if(id!=null){if((!Objects.equals(String.valueOf(old.get("room_type_id")),String.valueOf(tipo))||state.equals("INACTIVO"))&&jdbc.queryForObject("SELECT count(*)  FROM reservations WHERE room_id=? AND status IN ('CONFIRMADA','EN_ESTADIA','PENDIENTE_PAGO')",Integer.class,id)>0)throw ApiException.conflicto("RESERVAS_ACTIVAS","La habitación tiene reservas activas.");jdbc.update("UPDATE rooms SET number=?,floor=?,room_type_id=?,status=?,version=version+1 WHERE id=?",numero,piso,tipo,state,id);}else id=jdbc.queryForObject("INSERT INTO rooms(number,floor,room_type_id,status) VALUES(?,?,?,?) RETURNING id",Long.class,numero,piso,tipo,state);}
   case "personal"->{String nombre=texto(d,"nombre",150),correo=texto(d,"correo",150).toLowerCase(Locale.ROOT),telefono=texto(d,"telefono",30),rol=texto(d,"rol",30),state=estado(d);if(!correo.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+")||!Set.of("ADMIN","RECEPCION","ROOM_SERVICE","MANTENIMIENTO_LIMPIEZA").contains(rol))throw invalid("Revisa correo y rol.");if(!ValidacionesPersona.telefono(telefono))throw invalid("Teléfono inválido: usa de 7 a 15 dígitos y prefijo internacional opcional.");if(jdbc.queryForObject("SELECT count(*)  FROM employees WHERE lower(email)=? AND id<>?",Integer.class,correo,id==null?-1:id)>0)throw ApiException.conflicto("CORREO_EXISTENTE","El correo ya está asociado a otra cuenta.");String area=d.get("area")==null?null:String.valueOf(d.get("area"));if(rol.equals("MANTENIMIENTO_LIMPIEZA")?!Set.of("LIMPIEZA","MANTENIMIENTO","AMBAS").contains(Objects.toString(area,"")):area!=null&&!area.isBlank())throw invalid("Revisa el área del empleado.");if(!rol.equals("MANTENIMIENTO_LIMPIEZA"))area=null;
    if(id!=null&&"ADMIN".equals(old.get("role"))&&(!rol.equals("ADMIN")||state.equals("INACTIVO"))){var admins=jdbc.queryForList("SELECT id  FROM employees WHERE role='ADMIN' AND status='ACTIVO' FOR UPDATE",Long.class);if(admins.size()<2)throw ApiException.conflicto("ULTIMO_ADMIN","Debe conservarse un administrador activo.");}if(id!=null&&id==UsuarioActual.id()&&(!rol.equals("ADMIN")||state.equals("INACTIVO")))throw invalid("No puedes quitar tu propio acceso administrativo.");
    Object perfil=d.getOrDefault("perfil",Map.of());if(!(perfil instanceof Map<?,?> profile))throw invalid("Perfil inválido.");for(String key:List.of("salarioBase","bonosExtras","descuentosNomina"))if(profile.containsKey(key)){try{if(new BigDecimal(String.valueOf(profile.get(key))).signum()<0)throw invalid("Importes de nómina inválidos.");}catch(NumberFormatException e){throw invalid("Importes de nómina inválidos.");}}String json=mapper.writeValueAsString(perfil);
    if(id==null){temporal=texto(d,"accesoInicial",100);if(temporal.length()<12)throw invalid("La contraseña inicial debe tener al menos 12 caracteres.");id=jdbc.queryForObject("INSERT INTO employees(full_name,email,phone,role,area,status,password_hash,must_change_password,profile) VALUES(?,?,?,?,?,?,?,true,?::jsonb) RETURNING id",Long.class,nombre,correo,telefono,rol,area,state,encoder.encode(temporal),json);}else jdbc.update("UPDATE employees SET full_name=?,email=?,phone=?,role=?,area=?,status=?,profile=?::jsonb,version=version+1 WHERE id=?",nombre,correo,telefono,rol,area,state,json,id);
   }
   case "temporadas"->{String nombre=texto(d,"nombre",100);LocalDate desde,hasta;try{desde=LocalDate.parse(texto(d,"desde",10));hasta=LocalDate.parse(texto(d,"hasta",10));}catch(java.time.format.DateTimeParseException e){throw invalid("Fechas inválidas.");}if(hasta.isBefore(desde))throw invalid("La fecha final debe ser posterior o igual al inicio.");BigDecimal ajuste=num(d,"ajustePct",new BigDecimal("-99.99"));boolean all=Boolean.TRUE.equals(d.get("aplicaATodos")),active=Boolean.TRUE.equals(d.get("activa"));Object list=d.get("tipos");if(!(list instanceof List<?> ids))throw invalid("Selecciona los tipos de habitación.");if(!all&&ids.isEmpty())throw invalid("Selecciona al menos un tipo.");Set<Long> tipos=new HashSet<>();for(Object value:ids){long v;try{v=Long.parseLong(value.toString());}catch(NumberFormatException e){throw invalid("Tipo inválido.");}if(jdbc.queryForObject("SELECT count(*)  FROM room_types WHERE id=?",Integer.class,v)!=1)throw invalid("Tipo inexistente.");tipos.add(v);}
    if(active){jdbc.queryForObject("SELECT pg_advisory_xact_lock(1648021)",Object.class);var overlap=jdbc.queryForList("SELECT id,applies_to_all AS \"aplica_a_todos\" FROM seasons WHERE active AND start_date<=? AND end_date>=? AND id<>?",hasta,desde,id==null?-1:id);for(var o:overlap){if(all||Boolean.TRUE.equals(o.get("aplica_a_todos")))throw ApiException.conflicto("TEMPORADA_SOLAPADA","Ya existe una temporada activa en esas fechas.");var assigned=jdbc.queryForList("SELECT room_type_id AS \"tipo_habitacion_id\" FROM season_room_types WHERE season_id=?",Long.class,o.get("id"));if(assigned.stream().anyMatch(tipos::contains))throw ApiException.conflicto("TEMPORADA_SOLAPADA","Hay temporadas superpuestas para ese tipo.");}}
    if(id==null)id=jdbc.queryForObject("INSERT INTO seasons(name,start_date,end_date,adjustment_pct,applies_to_all,active) VALUES(?,?,?,?,?,?) RETURNING id",Long.class,nombre,desde,hasta,ajuste,all,active);else jdbc.update("UPDATE seasons SET name=?,start_date=?,end_date=?,adjustment_pct=?,applies_to_all=?,active=?,version=version+1 WHERE id=?",nombre,desde,hasta,ajuste,all,active,id);
    // Se conservan las asociaciones históricas al archivar. En edición, se añaden los tipos nuevos;
    // no se permite cambiar el conjunto de una temporada existente: crear otra y archivar evita borrar historia.
    if(p.id()!=null){var assigned=new HashSet<>(jdbc.queryForList("SELECT room_type_id AS \"tipo_habitacion_id\" FROM season_room_types WHERE season_id=?",Long.class,id));if(!assigned.equals(tipos))throw invalid("Para cambiar los tipos, archiva esta temporada y crea otra.");}for(long tipo:tipos)jdbc.update("INSERT INTO season_room_types(season_id,room_type_id) VALUES(?,?) ON CONFLICT DO NOTHING",id,tipo);
   }
  }
  var nuevo=jdbc.queryForMap("SELECT to_jsonb(x)::text AS datos  FROM "+t+" x WHERE id=?",id);Map<String,Object> audit=mapper.readValue((String)nuevo.get("datos"),Map.class);audit.remove("password_hash");jdbc.update("INSERT INTO administration_audit(resource,record_id,employee_id,previous,new) VALUES(?,?,?,?::jsonb,?::jsonb)",recurso,id,UsuarioActual.id(),old==null?null:mapper.writeValueAsString(old),mapper.writeValueAsString(audit));Map<String,Object> result=new LinkedHashMap<>();result.put("id",id);result.put("version",audit.get("version"));return result;
 }
}
